import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), q = nextInt();
        long w = nextLong();
        long[] logs = new long[m], qs = new long[q];
        for (int i = 0; i < m; i++) {
            long skill = nextLong(), t = nextLong();
            logs[i] = t << 20 | skill;
        }
        for (int i = 0; i < q; i++) qs[i] = nextLong() << 20 | i;
        Arrays.sort(logs);
        Arrays.sort(qs);
        final long LOW = (1 << 20) - 1;
        int[] counts = new int[n + 1], answer = new int[q];
        int left = 0, right = 0, active = 0;
        for (long e : qs) {
            long t = e >> 20;
            int index = (int) (e & LOW);
            while (right < m && (logs[right] >> 20) <= t) {
                int skill = (int) (logs[right] & LOW);
                if (counts[skill]++ == 0) active++;
                right++;
            }
            while (left < right && (logs[left] >> 20) < t - w) {
                int skill = (int) (logs[left] & LOW);
                if (--counts[skill] == 0) active--;
                left++;
            }
            answer[index] = n - active;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            if (i > 0) sb.append(' ');
