package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, q, w := nextInt(), nextInt(), nextInt(), nextInt()
	logs := make([]int, m)
	for i := range logs {
		skill, t := nextInt(), nextInt()
		logs[i] = t<<20 | skill
	}
	qs := make([]int, q)
	for i := range qs {
		qs[i] = nextInt()<<20 | i
	}
	sort.Ints(logs)
	sort.Ints(qs)
	const low = 1<<20 - 1
	counts := make([]int, n+1)
	answer := make([]int, q)
	left, right, active := 0, 0, 0
	for _, e := range qs {
		t, index := e>>20, e&low
		for right < m && logs[right]>>20 <= t {
			skill := logs[right] & low
			if counts[skill] == 0 {
				active++
			}
			counts[skill]++
			right++
		}
		for left < right && logs[left]>>20 < t-w {
			skill := logs[left] & low
			counts[skill]--
			if counts[skill] == 0 {
				active--
			}
			left++
		}
		answer[index] = n - active
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i, v := range answer {
		if i > 0 {
			out.WriteByte(' ')
		}
		out.WriteString(strconv.Itoa(v))
	}
	out.WriteByte('\n')
}
